import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export function getPlanLimits(plan: PlanId): PlanLimits {
  return PLAN_LIMITS[plan];
}

/** Reads one numeric quota without the caller destructuring `PlanLimits`. */
export function getLimit(plan: PlanId, resource: LimitedResource): number {
  return getPlanLimits(plan)[resource];
}

/** True when `plan` is at least as rich as `minPlan`. */
export function planAtLeast(plan: PlanId, minPlan: PlanId): boolean {
  return PLAN_ORDER.indexOf(plan) >= PLAN_ORDER.indexOf(minPlan);
}

/** True when consuming `requested` more units would breach the quota. */
export function wouldExceedLimit(
  plan: PlanId,
  resource: LimitedResource,
  used: number,
  requested = 1,
): boolean {
  return used + requested > getLimit(plan, resource);
}
/**
 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
 *
 * Must call (do not reimplement): emit, shouldFilterArchived
 */
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { shouldFilterArchived } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

/** How many organizations one pass sweeps. */
const ORG_BATCH = 50;

/** Archived issues are never overdue — an archived issue has no due date. */
const LIVE_ONLY = {} as const;

const logger = createLogger("overdue-issue-job");

/**
 * Issues already announced this process's lifetime. A later sweep still
 * finds a still-open, still-overdue issue — this is what keeps the job from
 * re-emitting `issue.overdue` for it on every pass.
 */
const reported = new Set<string>();

/** Test-only: clears the reported set so a fresh scenario starts empty. */
export function resetOverdueTracking(): void {
  reported.clear();
}

/**
 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
 * no notification logic: it announces the fact, and whoever cares (in-app
 * alerts, the digest, webhooks) reacts on the bus.
 */
export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
  return runJob("overdue-issues", async (result) => {
    if (!shouldFilterArchived(LIVE_ONLY)) {
      logger.warn("archive scope misconfigured; skipping sweep", {});
      return;
    }

    const stamp = toIsoTimestamp(now);
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);

      for (const issue of overdue) {
        if (issue.dueAt === null) continue;
        if (reported.has(issue.id)) continue;

        try {
          await emit("issue.overdue", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            issueId: issue.id,
            projectId: issue.projectId,
            dueAt: issue.dueAt,
            assigneeId: issue.assigneeId,
          });
          reported.add(issue.id);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to announce overdue issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}
/**
 * Barrel for the job layer.
 *
 * `instrumentation.ts` imports `startScheduler` from here; everything else in
 * the app talks to jobs by emitting an event, never by calling a runner
 * directly. The individual `run*Job` functions are exported for the admin
 * "run now" action and for the test suite.
 */
export {
  drain,
  enqueue,
  pendingCount,
  resetQueue,
} from "./queue";
export type { JobKind, QueuedJob } from "./queue";

export {
  isSchedulerRunning,
  startScheduler,
  stopScheduler,
  tick,
} from "./scheduler";

export { emptyJobResult } from "./types";
export type { JobResult } from "./types";

export { runCleanupArchivedJob } from "./cleanup-archived-job";
export { runDigestEmailJob, shouldRunForOrg } from "./digest-email-job";
export { runOverdueIssueJob } from "./overdue-issue-job";
export { runSearchReindexJob } from "./search-reindex-job";
export { runTrialExpiryJob } from "./trial-expiry-job";
export { runUsageRollupJob } from "./usage-rollup-job";
export { backoffMs, runWebhookDeliveryJob } from "./webhook-delivery-job";
/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}

