  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  createdBy: UserId;
}

function toRecurringIssue(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    projectId: row.projectId as ProjectId,
    title: row.title,
    priority: row.priority as IssuePriority,
    assigneeId: row.assigneeId as UserId | null,
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: row.createdBy as UserId,
    createdAt: row.createdAt as IsoTimestamp,
    updatedAt: row.updatedAt as IsoTimestamp,
  };
}

/**
 * Counts and inserts in one synchronous step so two concurrent creates cannot
 * both slip under the cap. Returns `null` when the cap would be exceeded.
 */
export async function insertWithinQuota(
  input: NewRecurringIssue,
  maxRules: number,
): Promise<RecurringIssue | null> {
  const db = getDb();
  const used =
    db
      .select({ value: count() })
      .from(recurringIssues)
      .where(orgPredicate(recurringIssues.orgId, input.orgId))
      .get()?.value ?? 0;
  if (used + 1 > maxRules) return null;

  const stamp = toIsoTimestamp(new Date());
  const row = db
    .insert(recurringIssues)
    .values({
      id: newId(),
      ...input,
      lastOccurrenceOn: null,
      paused: false,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function findRule(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function listRules(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), sql`rowid`)
    .all()
    .map(toRecurringIssue);
}

/** Cross-tenant on purpose: the job sweeps every organization's live rules. */
export async function listActiveRules(): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), sql`rowid`)
    .all()
    .map(toRecurringIssue);
}

export async function setPaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function setLastOccurrence(
  orgId: OrgId,
  id: string,
  day: string,
): Promise<void> {
  getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn: day, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)),
    )
    .run();
}
